<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { message } from 'ant-design-vue'
import { PlusOutlined } from '@ant-design/icons-vue'
import api from '@/api/client'
import PageBackButton from '@/components/PageBackButton.vue'
const jobs=ref<any[]>([]); const applications=ref<any[]>([]); const loading=ref(false); const jobDrawer=ref(false); const detail=ref<any>(null); const detailOpen=ref(false)
const jobForm=reactive({title:'',department:'',location:'Singapore',employment_type:'实习',description:'',requirements:'',status:'开放'})
async function load(){loading.value=true;try{jobs.value=(await api.get('/api/v1/recruitment/jobs')).data.data;applications.value=(await api.get('/api/v1/recruitment/applications')).data.data}catch(error:any){message.error(error.response?.data?.detail || '管理数据加载失败')}finally{loading.value=false}}
async function createJob(){try{await api.post('/api/v1/recruitment/jobs',jobForm);message.success('岗位已创建');jobDrawer.value=false;Object.assign(jobForm,{title:'',department:'',location:'Singapore',employment_type:'实习',description:'',requirements:'',status:'开放'});await load()}catch(error:any){message.error(error.response?.data?.detail || '创建岗位失败')}}
async function changeStatus(item:any,status:string){try{await api.patch(`/api/v1/recruitment/applications/${item.id}/status`,{status,review_note:item.review_note || '管理员人工更新'});message.success('候选人状态已更新');await load()}catch(error:any){message.error(error.response?.data?.detail || '状态更新失败')}}
onMounted(load)
</script>
<template><div class="page-frame business-page"><header class="page-heading"><div><p class="eyebrow">B-SIDE RECRUITMENT</p><h1>招聘管理端</h1><p>岗位和候选人数据均来自后端数据库，当前由管理员人工筛选。</p></div><div class="heading-actions"><PageBackButton fallback="/modules/resume-screening"/><a-button type="primary" @click="jobDrawer=true"><PlusOutlined/> 新增岗位</a-button></div></header><a-spin :spinning="loading"><section class="business-grid two-columns"><a-card class="plain-panel" :bordered="false"><h2>岗位管理</h2><a-table size="small" :pagination="false" :data-source="jobs" :columns="[{title:'岗位名称',dataIndex:'title'},{title:'部门',dataIndex:'department'},{title:'地点',dataIndex:'location'},{title:'状态',dataIndex:'status'}]" row-key="id"><template #bodyCell="{column,record}"><template v-if="column.dataIndex==='status'"><a-tag :color="record.status==='开放'?'green':'default'">{{record.status}}</a-tag></template></template></a-table></a-card><a-card class="plain-panel"><h2>候选人池</h2><a-empty v-if="!applications.length" description="暂无候选人投递"/><a-table v-else size="small" :pagination="{pageSize:8}" :data-source="applications" :columns="[{title:'候选人',dataIndex:'name'},{title:'岗位',dataIndex:'job_title'},{title:'学校/专业',dataIndex:'school'},{title:'状态',dataIndex:'status'},{title:'操作',dataIndex:'actions'}]" row-key="id"><template #bodyCell="{column,record}"><template v-if="column.dataIndex==='school'"><span>{{record.school || '—'}} / {{record.major || '—'}}</span></template><template v-if="column.dataIndex==='status'"><a-select :value="record.status" size="small" style="width:110px" :options="['待初筛','待面试','已通过','不合适'].map(value=>({label:value,value}))" @change="(value:string)=>changeStatus(record,value)"/></template><template v-if="column.dataIndex==='actions'"><a-button size="small" @click="detail=record;detailOpen=true">查看简历</a-button></template></template></a-table></a-card></section></a-spin><a-drawer v-model:open="jobDrawer" title="新增岗位" width="560"><a-form layout="vertical"><a-form-item label="岗位名称" required><a-input v-model:value="jobForm.title"/></a-form-item><a-form-item label="部门" required><a-input v-model:value="jobForm.department"/></a-form-item><a-form-item label="地点" required><a-input v-model:value="jobForm.location"/></a-form-item><a-form-item label="岗位描述" required><a-textarea v-model:value="jobForm.description" :rows="4"/></a-form-item><a-form-item label="岗位要求" required><a-textarea v-model:value="jobForm.requirements" :rows="4"/></a-form-item><a-button type="primary" block @click="createJob">保存岗位</a-button></a-form></a-drawer><a-drawer v-model:open="detailOpen" title="候选人详情" width="560"><a-descriptions v-if="detail" bordered :column="1"><a-descriptions-item label="姓名">{{detail.name}}</a-descriptions-item><a-descriptions-item label="邮箱">{{detail.email}}</a-descriptions-item><a-descriptions-item label="学校/专业">{{detail.school}} / {{detail.major}}</a-descriptions-item><a-descriptions-item label="简历内容"><pre style="white-space:pre-wrap">{{detail.resume_text || '未填写'}}</pre></a-descriptions-item><a-descriptions-item label="求职说明">{{detail.cover_note || '未填写'}}</a-descriptions-item></a-descriptions></a-drawer></div></template>
